import {
    ts,
    type Shape,
    type ObjectShape,
    type Diagnostics,
    type Compiler,
    type PluginApiDoc,
} from '@servicenow/sdk-build-core'

export function toReference(shape: Shape) {
    return shape.ifRecord()?.getId() ?? shape.ifString()?.getValue() ?? ''
}

/**
 * Reverses an object, swapping keys and values. **reverseObject** should only be used
 * where the key/values are all known ahead of time and the values are unique.
 * @example
 * reverseObject({ a: 'foo', b: 'bar' }) // { foo: 'a', bar: 'b' }
 */
export function reverseObject<K extends string, V extends string>(obj: Record<K, V>) {
    const reversed = {} as Record<V, K>
    for (const key in obj) {
        const value = obj[key]
        if (typeof value === 'string') {
            reversed[value] = key
        }
    }
    return reversed
}

export function noThrow<T>(action: () => T) {
    try {
        return action()
    } catch (error) {
        return error as Error
    }
}

/**
 * Regex taken from: https://github.com/oozcitak/xmlbuilder-js/blob/b20136cd1591d0f17ab2f184053c7150150428b2/src/XMLStringifier.coffee#L119C15-L119C127
 */
export const INVALID_XML_CHARACTERS =
    // biome-ignore lint/suspicious/noControlCharactersInRegex: This is intentional
    /[\0-\x08\x0B\f\x0E-\x1F\uFFFE\uFFFF]|[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?:[^\uD800-\uDBFF]|^)[\uDC00-\uDFFF]/g

export function applyPathMappings(path: string, mappings: Record<string, string>) {
    if (!mappings) {
        return path
    }
    // TODO: Naive implementation for now that just supports simple patterns. We can explore supporting more complex patterns later.
    for (const [source, target] of Object.entries(mappings)) {
        const match = path.match(`${source.replace(/\./, '\\.').replace(/\*+/, '(.*)')}$`)?.[1]
        if (match !== undefined) {
            return target.replace(/\*+/, match)
        }
    }
    return path
}

export function getCallExpressionName(node: ts.CallExpression) {
    const expression = node.getExpression()
    if (ts.Node.isIdentifier(expression) || ts.Node.isPropertyAccessExpression(expression)) {
        return expression.getText()
    }

    throw `CallExpression does not have a name: ${expression.getText()}`
}

export function generateDeprecatedDiagnostics(object: ObjectShape, diagnostics: Diagnostics): void {
    Object.keys(object.getAliasedKeys()).forEach((key) => {
        const alias = object.findAliasUsed(key)
        if (alias) {
            diagnostics.hint(object.get(key), `The property '${alias}' is deprecated, use '${key}' instead.`)
        }
    })
}

/**
 * Helper function to check if a call expression is a require statement
 */
function isRequire(callExpression: ts.CallExpression): boolean {
    const expression = callExpression.getExpression()
    return ts.Node.isIdentifier(expression) && expression.getText() === 'require'
}

/**
 * Validates that client-side scripts (Client Scripts and UI Policy scripts) don't contain
 * import or require statements. These scripts run in the browser and cannot use module imports.
 *
 * @param script - The script content to validate
 * @param compiler - The TypeScript compiler instance
 * @returns true if the script is valid (no imports/requires), false otherwise
 */
export function validateClientSideScript(script: string, compiler: Compiler): boolean {
    const source = compiler.createSourceFile('tmp-script.ts', script)
    const hasImports = source.getDescendantsOfKind(ts.SyntaxKind.ImportDeclaration).length > 0
    const hasRequires = source.getDescendantsOfKind(ts.SyntaxKind.CallExpression).some(isRequire)
    const isValid = !(hasImports || hasRequires)
    compiler.removeSourceFile(source)

    return isValid
}

/**
 * Creates a documentation entry for first-party SDK plugins.
 * Using this helper ensures apiName and docPath are always in sync.
 *
 * @param apiName - The API name (e.g., 'BusinessRule', 'Acl')
 * @param tags - Keywords for categorization (typically includes the ServiceNow table name)
 * @returns A complete PluginApiDoc entry
 */
export function createSdkDocEntry(apiName: string, tags: string[]): PluginApiDoc {
    return {
        apiName,
        docPath: `@servicenow/sdk/docs/${apiName}/${apiName}.md`,
        tags,
    }
}
